 const draw=()=>{let shown=data.filter(x=>(!isRecipes||listing.category==='all'||x.category===listing.category)&&JSON.stringify(x).toLowerCase().includes(query.toLowerCase()));if(sort.dir)shown=[...shown].sort((a,b)=>compare(a[sort.key],b[sort.key])*sort.dir);$('#records-count').textContent=`Записей: ${shown.length}`;if(isRecipes){$('#recipe-grid').innerHTML=shown.map(x=>`<article class="recipe-tile" data-id="${x.recipe_id}" tabindex="0" title="Открыть рецепт"><div class="recipe-tile-head"><span class="recipe-id">${x.recipe_id}</span><span class="pill">${x.status}</span></div><div class="recipe-category">${categoryInfo[x.category]?.[0]||x.category}</div><h3>${x.name}</h3><p>${x.subcategory||x.tags||'Рецепт из личной коллекции'}</p><div class="tile-macros"><span><b>${fmt(x.kcal_per_serving)}</b><small>ккал</small></span><span><b>${fmt(x.protein_per_serving_g)}</b><small>белки</small></span><span><b>${fmt(x.fat_per_serving_g)}</b><small>жиры</small></span><span><b>${fmt(x.carbs_per_serving_g)}</b><small>углев.</small></span></div><div class="recipe-tile-foot"><span>v${x.version}</span><b>${fmt(x.cost_per_serving_rsd)} RSD ${x.manual_price_per_serving_rsd!=null?'<small>фикс.</small>':''}</b></div></article>`).join('')||`<div class="panel empty">Ничего не найдено</div>`}else{$('#tbody').innerHTML=shown.map(x=>`<tr>${cols.map(c=>`<td class="${typeof x[c[0]]==='number'?'number':''}">${c[0]==='status'||c[0]==='data_status'?`<span class="pill">${x[c[0]]}</span>`:c[0].includes('date')||c[0].includes('_at')?date(x[c[0]]):fmtValue(x[c[0]])}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${cols.length}" class="empty">Ничего не найдено</td></tr>`;document.querySelectorAll('.sort-button').forEach(b=>b.querySelector('span').textContent=sort.key===b.dataset.key?(sort.dir===1?'↑':'↓'):'↕')}$('#reset-sort').disabled=!sort.dir};
