function compare(a,b){if(a==null&&b==null)return 0;if(a==null)return 1;if(b==null)return-1;if(typeof a==='number'&&typeof b==='number')return a-b;const da=Date.parse(a),db=Date.parse(b);if(!Number.isNaN(da)&&!Number.isNaN(db)&&String(a).match(/^\d{4}-/))return da-db;return String(a).localeCompare(String(b),'ru',{numeric:true,sensitivity:'base'})}
function fmtValue(v){return typeof v==='number'?fmt(v):(v??'—')}
