 f.innerHTML=`<div class="grid">${input('recipe_id','ID рецепта',r.recipe_id,'text','readonly tabindex="-1"')}${options('category','Категория',categories,r.category)}${input('name','Название',r.name,'text','required')}${input('subcategory','Подкатегория',r.subcategory||'')}${input('version','Версия',r.version)}${options('status','Статус',[['Draft','Draft'],['Testing','Testing'],['Approved','Approved'],['Archived','Archived']],r.status)}${input('servings','Количество порций',r.servings,'number','min="1" step="0.1" required')}${input('tags','Теги',r.tags||'')}${input('manual_price_per_serving_rsd','Фиксированная цена за порцию, RSD',r.manual_price_per_serving_rsd??'','number','min="0" step="0.01" placeholder="Пусто = рассчитать по составу"')}</div><div class="field full" style="margin-top:16px"><label>Ингредиенты</label><div id="ingredients"></div><button type="button" id="add-ing">＋ ингредиент</button></div>`;
