 const add=(item={})=>{$('#ingredients').insertAdjacentHTML('beforeend',`<div class="ingredient-row"><select class="ip">${sortedProducts.map(p=>`<option value="${p.product_id}" data-unit="${p.unit}" ${p.product_id===item.product_id?'selected':''}>${p.name}</option>`)}</select><input class="iq" type="number" step="0.01" value="${item.quantity??''}" placeholder="Количество" required><button type="button" onclick="this.parentElement.remove()">×</button></div>`)};detail.ingredients.forEach(add);if(!detail.ingredients.length)add();$('#add-ing').onclick=()=>add();const syncRecipeMode=()=>{const ready=category.value==='Ready';f.querySelector('.ready-recipe-fields').hidden=!ready;ingredientsSection.hidden=ready;f.querySelectorAll('.ready-recipe-fields input').forEach(control=>control.required=ready);f.querySelectorAll('.iq').forEach(control=>control.required=!ready)};category.addEventListener('change',syncRecipeMode);syncRecipeMode();
