const field=(name,label,type='text',extra='')=>`<div class="field"><label>${label}</label><input name="${name}" type="${type}" ${extra}></div>`, select=(name,label,opts)=>`<div class="field"><label>${label}</label><select name="${name}">${opts.map(x=>`<option value="${x[0]}">${x[1]}</option>`).join('')}</select></div>`;
function setupProductPriceCalculation(container){const price=container.querySelector('[name="package_price_rsd"]'),size=container.querySelector('[name="package_size"]'),unit=container.querySelector('[name="unit"]'),result=container.querySelector('[name="price_per_100_or_unit_rsd"]');if(!price||!size||!unit||!result)return;const label=result.closest('.field').querySelector('label'),calculate=()=>{const packagePrice=Number(price.value),packageSize=Number(size.value),isWeight=unit.value==='г'||unit.value==='мл';label.textContent=isWeight?`Цена за 100 ${unit.value}`:`Цена за 1 ${unit.value}`;result.value=price.value!==''&&size.value!==''&&packageSize>0?(packagePrice/packageSize*(isWeight?100:1)).toFixed(2):''};[price,size,unit].forEach(control=>control.addEventListener(control===unit?'change':'input',calculate));calculate()}
function setupProductKcalCalculation(container){const kcal=container.querySelector('[name="kcal"]'),protein=container.querySelector('[name="protein_g"]'),fat=container.querySelector('[name="fat_g"]'),carbs=container.querySelector('[name="carbs_g"]');if(!kcal||!protein||!fat||!carbs)return;let automatic=kcal.value==='';const calculate=()=>{if(!automatic)return;kcal.value=((Number(protein.value)||0)*4+(Number(fat.value)||0)*9+(Number(carbs.value)||0)*4).toFixed(2).replace(/\.00$/,'')};kcal.addEventListener('input',()=>{automatic=kcal.value==='';calculate()});[protein,fat,carbs].forEach(control=>control.addEventListener('input',calculate));calculate()}
function setupProgressCalculations(container){const get=name=>container.querySelector(`[name="${name}"]`),weight=get('weight_kg'),height=get('height_cm'),fat=get('body_fat_pct'),muscle=get('muscle_pct'),bmi=get('bmi'),fatMass=get('fat_mass_kg'),muscleMass=get('muscle_mass_kg');if(!weight||!height)return;const calculate=()=>{const w=Number(weight.value),h=Number(height.value),f=Number(fat.value),m=Number(muscle.value);bmi.value=weight.value!==''&&height.value!==''&&h>0?(w/((h/100)**2)).toFixed(2):'';fatMass.value=weight.value!==''&&fat.value!==''?(w*f/100).toFixed(2):'';muscleMass.value=weight.value!==''&&muscle.value!==''?(w*m/100).toFixed(2):''};[weight,height,fat,muscle].forEach(control=>control.addEventListener('input',calculate));calculate()}
const localToday=()=>{const now=new Date();return dayIso(now.getFullYear(),now.getMonth(),now.getDate())};
const diaryRow=(recipes,item={})=>`<div class="diary-form-row"><select class="dm">${mealOrder.map(meal=>`<option ${meal===item.meal_type?'selected':''}>${meal}</option>`)}</select><select class="dr">${recipes.map(recipe=>`<option value="${recipe.recipe_id}" ${recipe.recipe_id===item.recipe_id?'selected':''}>${recipe.name}</option>`)}</select><input class="ds" type="number" min="0.25" step="0.25" value="${item.servings??1}" aria-label="Порций" required><input class="dc" value="${item.comment||''}" placeholder="Комментарий"><button type="button" class="remove-diary-row" aria-label="Удалить блюдо">×</button></div>`;
